/**
 * A joined row of segments that always holds one value (`design/components/segmented-control.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/segmented-control.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/radio-group'

import {
  Icon,
  KEEPS_HOLDER,
  KEEPS_IDENTITY,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  derived,
  elementRef,
  lenderHolder,
  lentIdentity,
  mountEffect,
  normalizeProps,
  presence,
  roveRadio,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  type Each,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/segmented-control.module.css'

export type SegmentedControlSize = NonNullable<SegmentedControlProps['size']>

export interface SegmentedControlOption {
  value: string
  label: string
  icon?: IconRole
  disabled?: boolean
}

/** A joined row of segments that always holds one value: the inputs it takes, by the React member's prop names. */
export interface SegmentedControlProps {
  defaultValue?: string
  /**
   * Disables the whole group. Use `disabled` in `options` for single options.
   */
  disabled?: boolean
  /**
   * The group's accessible name, because outside a form there is no FormField to name it.
   */
  label: string
  /**
   * Items render from data, because free-form children invite ad hoc layouts (Radio's law).
   */
  options: SegmentedControlOption[]
  /**
   * There is no `lg`, on purpose. A segmented control is an inline control used in toolbars,
   * page headers and filter rows next to `sm`/`md` controls. A form-sized single choice is
   * RadioGroup in a FormField, not this at 44px.
   */
  size?: 'sm' | 'md'
  value?: string
}

/** A joined row of segments that always holds one value. */
@Component({
  selector: 'pm-segmented-control',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  viewProviders: [...KEEPS_IDENTITY, ...KEEPS_HOLDER],
  imports: [Ref, Icon],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
role="radiogroup"
[attr.aria-label]="e2()"
[attr.data-size]="e3()"
[attr.data-disabled]="e4()"
[attr.data-member]="e5()"
[pmRef]="track"
>@for (option of e6(); track e7(option)) {<!-- segment -->
<button
[attr.class]="e8()"
type="button"
role="radio"
[attr.value]="e7(option)"
[attr.aria-checked]="e9(option)"
[attr.disabled]="e10(option)"
[attr.tabindex]="e11(option)"
[attr.data-state]="e12(option)"
[attr.data-disabled]="e13(option)"
(click)="h1(option)"
(keydown)="h2($event)"
>@if (e9(option)) {<span
[attr.class]="e14(option)"
data-state="checked"
></span>}
@if (e15(option)) {<span
[attr.class]="e16(option)"
><pm-icon
[name]="e17(option)"
[size]="e18(option)"
></pm-icon></span>}
<span
[attr.class]="e19()"
>{{ e20(option) }}</span></button>}</div>`,
})
export class SegmentedControl {
  readonly defaultValue = input<SegmentedControlProps['defaultValue']>(undefined)
  /**
   * Disables the whole group. Use `disabled` in `options` for single options.
   */
  readonly disabled = input<
    Exclude<SegmentedControlProps['disabled'], undefined>,
    SegmentedControlProps['disabled']
  >(false, {
    transform: (value: SegmentedControlProps['disabled']) => (value === undefined ? false : value),
  })
  /**
   * The group's accessible name, because outside a form there is no FormField to name it.
   */
  readonly label = input.required<SegmentedControlProps['label']>()
  /**
   * Items render from data, because free-form children invite ad hoc layouts (Radio's law).
   */
  readonly options = input.required<SegmentedControlProps['options']>()
  /**
   * There is no `lg`, on purpose. A segmented control is an inline control used in toolbars,
   * page headers and filter rows next to `sm`/`md` controls. A form-sized single choice is
   * RadioGroup in a FormField, not this at 44px.
   */
  readonly size = input<
    Exclude<SegmentedControlProps['size'], undefined>,
    SegmentedControlProps['size']
  >('md', {
    transform: (value: SegmentedControlProps['size']) => (value === undefined ? 'md' : value),
  })
  readonly value = input<SegmentedControlProps['value']>(undefined)
  readonly onChange = output<string>({ alias: 'change' })
  protected readonly $ = useMember({
    events: ['change'],
    props: {
      defaultValue: () => this.defaultValue(),
      disabled: () => this.disabled(),
      label: () => this.label(),
      options: () => this.options(),
      size: () => this.size(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly lent = lentIdentity()
  protected readonly lender = lenderHolder()
  protected readonly uid = uniqueId()
  protected readonly track = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection(() => this.track.value)
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          value: this.$p.value,
          defaultValue: this.$p.defaultValue ?? this.$p.options[0]?.value,
          disabled: this.$p.disabled,
          onValueChange: (details) => {
            this.$.emit(this.onChange, 'onChange', details.value ?? '')
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly stop = derived(
    () =>
      this.api.value.value ??
      this.$p.options.find((option) => !(this.$p.disabled || option.disabled === true))?.value,
  )
  private release2: (() => void) | undefined

  constructor() {
    mountEffect(() => this.effect1())
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return styles.track
  }

  protected e2() {
    return this.$p.label
  }

  protected e3() {
    return this.$p.size
  }

  protected e4() {
    return this.$p.disabled ? '' : undefined
  }

  protected e5() {
    return this.lent ?? 'segmented-control'
  }

  e6() {
    return this.$p.options
  }

  protected e7(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return option.value
  }

  protected e8() {
    return styles.segment
  }

  protected e9(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return this.api.value.value === option.value
  }

  protected e10(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return presence(this.$p.disabled || option.disabled === true)
  }

  protected e11(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return option.value === this.stop.value ? 0 : -1
  }

  protected e12(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return this.api.value.value === option.value ? 'checked' : 'unchecked'
  }

  protected e13(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return this.$p.disabled || option.disabled === true ? '' : undefined
  }

  protected h1(option: Each<ReturnType<SegmentedControl['e6']>>): void {
    this.api.value.setValue(option.value)
  }

  protected h2($event: KeyboardEvent): void {
    void ($event.key === 'Enter'
      ? $event.preventDefault()
      : roveRadio($event, (next) => this.api.value.setValue(next)))
  }

  protected e14(option: Each<ReturnType<SegmentedControl['e6']>>) {
    if (!(this.api.value.value === option.value)) return undefined as never
    return styles.chip
  }

  protected e15(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return option.icon !== undefined
  }

  protected e16(option: Each<ReturnType<SegmentedControl['e6']>>) {
    if (!(option.icon !== undefined)) return undefined as never
    return styles.glyph
  }

  protected e17(option: Each<ReturnType<SegmentedControl['e6']>>): IconProps['name'] {
    if (!(option.icon !== undefined)) return undefined as never
    return option.icon
  }

  protected e18(option: Each<ReturnType<SegmentedControl['e6']>>): IconProps['size'] {
    if (!(option.icon !== undefined)) return undefined as never
    return this.$p.size
  }

  protected e19() {
    return styles.label
  }

  protected e20(option: Each<ReturnType<SegmentedControl['e6']>>) {
    return option.label
  }

  private effect1(): void {
    void (this.lender && (this.lender.element = () => this.track.value))
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'SegmentedControl',
      element: () => this.track.value,
      state: () => ({
        value: this.api.value.value ?? null,
        options: this.$p.options.map((option) => ({
          id: option.value,
          label: option.label,
          ...(option.disabled === true ? { disabled: true } : {}),
        })),
        disabled: this.$p.disabled,
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => value !== this.api.value.value && this.api.value.setValue(value),
        },
      },
    })
    this.release2 = () => {
      ran()
    }
  }
}
